# owner: platform
"""Snap span start and end times to a fixed step, and label the results."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

HOUR_MINUTES = 60


def check_step(step: int) -> None:
    """Raise ValueError unless step is a positive divisor of an hour."""
    if step <= 0 or HOUR_MINUTES % step:
        raise ValueError(f"step must be a positive divisor of 60, got {step}")


def round_minute(minutes: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    return (minutes + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    """Snap both ends of a span. A span that collapses to nothing is an error."""
    start = round_minute(span.start, step)
    end = round_minute(span.end, step)
    if start >= end:
        raise ValueError(f"{format_span(span)} is empty at a {step} minute step")
    return Span(start, end)


def span_label(span: Span) -> str:
    """The span followed by its length, such as 09:00-17:15 (8h 15m)."""
    hours, minutes = divmod(span.minutes, HOUR_MINUTES)
    return f"{format_span(span)} ({hours}h {minutes}m)"


def rounded_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Round every span to the step and return one label per span, in order."""
    check_step(step)
    return [span_label(round_span(span, step)) for span in spans]

