# owner: platform
import unittest

from hourglass.rounding import check_step, round_minute, round_span, rounded_labels
from hourglass.models import Span


class StepTests(unittest.TestCase):
    def test_accepts_divisors_of_an_hour(self):
        for step in (1, 2, 3, 5, 6, 10, 12, 15, 20, 30, 60):
            with self.subTest(step=step):
                check_step(step)

    def test_rejects_zero_negative_and_uneven_steps(self):
        for step in (0, -15, 7, 25, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    check_step(step)

    def test_labels_reject_bad_step_even_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_multiple(self):
        self.assertEqual(round_minute(547, 15), 540)
        self.assertEqual(round_minute(548, 15), 555)

    def test_exact_half_rounds_up(self):
        self.assertEqual(round_minute(545, 10), 550)

    def test_end_of_day_is_kept(self):
        self.assertEqual(round_minute(1439, 60), 1440)

    def test_span_rounds_both_ends(self):
        self.assertEqual(round_span(Span(543, 1036), 15), Span(540, 1035))

    def test_span_that_collapses_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)


class LabelTests(unittest.TestCase):
    def test_label_shows_span_and_length(self):
        self.assertEqual(
            rounded_labels([Span(543, 1036)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span_in_order(self):
        spans = [Span(780, 1020), Span(540, 600)]
        self.assertEqual(
            rounded_labels(spans, 15), ["13:00-17:00 (4h 0m)", "09:00-10:00 (1h 0m)"]
        )

    def test_end_of_day_label(self):
        self.assertEqual(
            rounded_labels([Span(1430, 1439)], 15), ["23:45-24:00 (0h 15m)"]
        )

    def test_no_spans_gives_no_labels(self):
        self.assertEqual(rounded_labels([], 15), [])
